<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>WooCommerce إلى سلة</title><style>body{font-family:system-ui;margin:0;background:#f5f7fa;color:#172033}.wrap{max-width:1000px;margin:45px auto;padding:20px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:18px;padding:24px;margin:16px 0;box-shadow:0 8px 28px #0000000a}input,button{font:inherit;padding:12px;border-radius:10px;border:1px solid #d1d5db}input{width:calc(100% - 26px);margin:6px 0}button,.btn{background:#111827;color:white;border:0;cursor:pointer;text-decoration:none;display:inline-block;padding:12px 18px;border-radius:10px}.muted{color:#6b7280}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><h1>نقل منتجات WooCommerce إلى سلة</h1>@if(!session('salla_merchant_id'))<section class="card"><h2>ربط متجر سلة</h2><p class="muted">ابدأ بتفويض التطبيق للوصول إلى متجرك.</p><a class="btn" href="{{ route('salla.oauth.redirect') }}">ربط سلة</a></section>@else<section class="card"><h2>ربط WooCommerce</h2><form id="woo"><input name="store_url" placeholder="https://store.example.com" required><div class="grid"><input name="consumer_key" placeholder="Consumer Key" required><input name="consumer_secret" type="password" placeholder="Consumer Secret" required></div><button>اختبار وحفظ الاتصال</button></form><p id="result" class="muted"></p></section><section class="card"><h2>الحالة</h2><pre id="dash">جاري التحميل...</pre></section><script>const csrf=document.querySelector('meta[name=csrf-token]').content;async function req(url,opt={}){opt.headers={...(opt.headers||{}),'Accept':'application/json','X-CSRF-TOKEN':csrf};const r=await fetch(url,opt);const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.message||'Request failed');return j}async function load(){document.querySelector('#dash').textContent=JSON.stringify(await req('/api/v1/dashboard'),null,2)}document.querySelector('#woo').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{const j=await req('/api/v1/woocommerce/connections',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(f))});document.querySelector('#result').textContent='تم ربط WooCommerce بنجاح';await load()}catch(x){document.querySelector('#result').textContent=x.message}});load();</script>@endif</main></body></html>
